                                return Err(self.error(
                                    "SPX-T270",
                                    format!("invalid command I/O operation `{name}` call shape"),
                                    expr.span,
                                ));
                            }
                            frames.push(Frame::FinishHostCommandOp {
                                span: expr.span,
                                path,
                                op,
                                argument_count: args.len(),
                            });
                            frames.push(Frame::ChildNext {
                                children: args,
                                index: 0,
                                bindings,
                                path,
                                segment: Seg::Arg,
                            });
