                            .declarations
                            .declaration(&variant)
                            .is_none_or(|item| item.kind != DeclarationKind::Variant)
                        {
                            return Err(self.error(
                                "SPX-H001",
                                format!("constructor target `{type_name}` is not a variant"),
                                expr.span,
                            ));
                        }
