                            .declarations
                            .case_id(&variant, case_name)
                            .cloned()
                            .ok_or_else(|| {
                                self.error(
                                    "SPX-H001",
                                    format!("unresolved case `{type_name}::{case_name}`"),
                                    expr.span,
                                )
                            })?;
