                            id: paths.at(path).expression_id_with(function, &[source]),
                            ty: owner_ty.clone(),
                            ownership: self.expression_ownership(
                                &owner_ty,
                                OwnershipMode::Own,
                                expr.span,
                            )?,
                            kind: ResolvedExprKind::Place(Place {
