                        let end = args.next().expect("range has an end");
                        debug_assert!(args.next().is_none());
                        results.push(ResolvedExpr {
                            id: paths.at(path).expression_id(function),
                            ty,
                            ownership: OwnershipMode::Borrow,
                            kind: ResolvedExprKind::ByteRange {
