                    }
                    results.push(ResolvedExpr {
                        id: paths.at(path).expression_id(function),
                        ty,
                        ownership,
                        kind: ResolvedExprKind::Call {
                            callee: DeclarationId::new(op.id()),
                            type_arguments: Vec::new(),
                            instance: None,
                            args,
                        },
                        span,
                    });
